 seen=set(); out=[]
 for x in map(tuple,np.argwhere(A==val)):
  if x in seen: continue
  co={x};seen.add(x);q=deque([x])
  while q:
   r,c=q.popleft()
   for dr,dc in offsets:
    p=(r+dr,c+dc)
    if 0<=p[0]<A.shape[0] and 0<=p[1]<A.shape[1] and A[p]==val and p not in seen:
     seen.add(p);co.add(p);q.append(p)
  out.append(co)
