def transform(grid):
    a=np.array(grid,dtype=int)
    counts=Counter(a.ravel())
    marker=min((v for v in counts if v != 0), key=lambda v: counts[v])
    pts=np.argwhere(a==marker)
    r0,c0=pts.min(axis=0)
    shape={(int(r-r0),int(c-c0)) for r,c in pts}
    h=max(r for r,c in shape)+1
    w=max(c for r,c in shape)+1
    out=a.copy()
    for r in range(a.shape[0]-h+1):
        for c in range(a.shape[1]-w+1):
            cells=[(r+dr,c+dc) for dr,dc in shape]
            if all(a[rr,cc]==0 for rr,cc in cells):
                for rr,cc in cells:
                    out[rr,cc]=marker
    return out.tolist()
